def bellman_ford(nodes, edges, start):
    dist = {n: math.inf for n in nodes}
    dist[start] = 0

    # V-1 passes. No cleverness about which edge to look at.
    for _ in range(len(nodes) - 1):
        changed = False

        for frm, to, weight in edges:
            if dist[frm] == math.inf:
                continue                  # no route here yet
            if dist[frm] + weight < dist[to]:
                dist[to] = dist[frm] + weight
                changed = True

        if not changed:
