#include <limits>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

struct Edge { std::string from, to; int weight; };

std::map<std::string, double> bellmanFord(
    const std::vector<std::string>& nodes,
    const std::vector<Edge>& edges,
    const std::string& start) {
    const double INF = std::numeric_limits<double>::infinity();

    std::map<std::string, double> dist;
    for (const std::string& n : nodes) dist[n] = INF;
    dist[start] = 0;

    // V-1 passes. No cleverness about which edge to look at.
    for (size_t pass = 0; pass + 1 < nodes.size(); pass++) {
        bool changed = false;

        for (const Edge& e : edges) {
            if (dist[e.from] == INF) continue;   // no route here yet
            if (dist[e.from] + e.weight < dist[e.to]) {
                dist[e.to] = dist[e.from] + e.weight;
                changed = true;
            }
        }

        if (!changed) break;  // settled early, the rest of the passes are wasted
    }

    // One extra pass. If anything still improves, no shortest path exists.
    for (const Edge& e : edges) {
        if (dist[e.from] == INF) continue;
        if (dist[e.from] + e.weight < dist[e.to]) {
            throw std::runtime_error("Negative cycle: shortest paths are undefined");
        }
    }

    return dist;
}

